<template><view class="detail"><view v-if="album" class="intro"><image :src="album.coverUrl" mode="aspectFill"/><text class="title">{{album.albumTitle}}</text><text class="summary">{{album.albumIntro}}</text><text class="hint">{{album.payType==='0101'?'免费内容':'支持免费试听；付费播放暂未接入'}}</text><view class="links"><button size="mini" @click="openAssistant()">问问听见助手</button><button size="mini" @click="go('/pages/business/business')">我的订单与售后</button><button size="mini" @click="go('/pages/index/index')">返回首页</button></view></view><text class="error">{{error}}</text><view class="chapter" v-for="track in tracks" :key="track.id"><view><text>{{track.orderNum}} · {{track.trackTitle}}</text><text class="hint" v-if="track.mediaDuration>0">{{track.mediaDuration}} 秒</text></view><button size="mini" :disabled="!track.playable" @click="go('/pages/player/player?trackId='+track.id+'&albumId='+album.id)">{{track.playable?'播放':'暂不可播放'}}</button></view><view class="pager"><button size="mini" :disabled="page===1||busy" @click="change(-1)">上一页</button><text>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</text><button size="mini" :disabled="page*20>=total||busy" @click="change(1)">下一页</button></view></view></template>
<script setup lang="ts">
import {openAssistant} from "../../stores/assistant"

import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {listeningRequest} from '../../api/listening';
const album=ref<any>(null),tracks=ref<any[]>([]),page=ref(1),total=ref(0),error=ref(''),busy=ref(false);let albumId='';
function go(url:string){uni.navigateTo({url})}async function load(){busy.value=true;try{const data=await listeningRequest('/api/content/albums/'+albumId+'/tracks?page='+page.value);tracks.value=data.records;total.value=data.total}catch(e:any){error.value=e.message}finally{busy.value=false}}async function change(delta:number){page.value+=delta;await load()}
onLoad(async(options:any)=>{albumId=options.id||'900001';try{album.value=await listeningRequest('/api/content/albums/'+albumId);await load()}catch(e:any){error.value=e.message}});
</script><style scoped>.detail{padding:32rpx;background:#f3f5ef;min-height:100vh}.intro{padding:32rpx;background:white;border-radius:20rpx}.intro image{width:200rpx;height:200rpx;border-radius:14rpx}.title{display:block;font-size:36rpx;font-weight:bold;margin:24rpx 0}.summary{display:block;line-height:1.8}.hint{display:block;font-size:24rpx;color:#789183;line-height:1.8;margin:12rpx 0}.links,.pager{display:flex;gap:12rpx;flex-wrap:wrap;margin-top:24rpx;align-items:center}.chapter{display:flex;justify-content:space-between;align-items:center;padding:24rpx;background:white;border-radius:16rpx;margin:20rpx 0;gap:24rpx}.chapter>view{flex:1}button{background:#244f45;color:white;margin:0}.error{color:#a04836}.detail{max-width:1060px;margin:auto;padding:32px 28px 100px;background:#f8f8f2}.intro{border:1px solid #e0e6d8;padding:30px;border-radius:22px}.title{font-size:28px;line-height:1.5}.summary{font-size:14px;color:#6d7e66}.hint{font-size:12px;color:#8b997f}.chapter{padding:20px 24px;border:1px solid #e0e6d8;border-radius:14px;font-size:14px}.links button,.pager button,.chapter button{font-size:12px;border-radius:9px;padding:10px 15px;line-height:1.6}.intro image{width:170px;height:170px;border-radius:16px}.error{display:block;margin:10px 0;font-size:13px}@media(max-width:600px){.detail{padding:20px 18px 90px}.intro{padding:22px}.intro image{width:130px;height:130px}.title{font-size:22px}.summary{font-size:13px}.chapter{padding:18px;font-size:13px;gap:12px}.links{gap:8px}.links button{font-size:11px}.links button,.pager button{padding:8px 12px}.hint{font-size:11px}}</style>